import type { SatRecords, SatSource } from "./sat-records";

/**
 * The SAT documents in `docs/sat-md`, generated by `sat-knowledge.ts`: the Anexo 20 and Pagos 2.0
 * guides, the error matrix and the catalogs. `corpus.ts` splits the guides into search passages
 * with `documentSections`.
 */
export type SatDocumentMetadata = {
  readonly slug: string;
  /** Labels a guide's preamble section, so it is part of that passage's key: never change it. */
  readonly title: string;
  /** The SAT file it comes from, a key of `docs/sat-md/sources.json`. */
  readonly sourceId: keyof SatSourceManifest;
  /** Its file name in `docs/sat-md`. */
  readonly file: string;
};

export type SatDocument = Omit<SatDocumentMetadata, "sourceId" | "file"> & {
  readonly markdown: string;
  /** The SAT file's URL. */
  readonly source: string;
  /** The date the SAT published that file. */
  readonly publishedAt: string | null;
};

/** `docs/sat-md/sources.json`: each SAT file, its hash, and the files generated from it. */
export type SatSourceManifest = Readonly<
  Record<"anexo20" | "pagos" | "matrix" | "catalogs", SatSource>
>;

/**
 * The SAT Markdown without its table padding: cells padded to hundreds of spaces left a search
 * passage mostly blank. Lines stay as they were, so line numbers still match the source.
 */
export function compactSatMarkdown(markdown: string) {
  return markdown
    .split("\n")
    .map((line) => line.replaceAll(/ {2,}/gu, " ").replaceAll(/-{4,}/gu, "---"))
    .join("\n");
}

export const SAT_DOCUMENTS: readonly SatDocumentMetadata[] = [
  {
    slug: "anexo-20-guia-de-llenado-cfdi",
    title: "Anexo 20: CFDI 4.0 filling guide",
    sourceId: "anexo20",
    file: "anexo-20-guia-de-llenado-cfdi.md",
  },
  {
    slug: "complemento-pagos-guia-de-llenado",
    title: "Payment complement (REP, Pagos 2.0) filling guide",
    sourceId: "pagos",
    file: "complemento-pagos-guia-de-llenado.md",
  },
  {
    slug: "matriz-de-errores-cfdi-4-0",
    title: "CFDI 4.0 error matrix (CFDI40xxx)",
    sourceId: "matrix",
    file: "matriz-de-errores-cfdi-4.0.md",
  },
  {
    slug: "catalogos-cfdi-4-0",
    title: "CFDI 4.0 catalogs (catCFDI)",
    sourceId: "catalogs",
    file: "catalogos-cfdi-4.0.md",
  },
];

/** The documents as read from disk, with the matrix and catalogs as records. */
export type SatLibrary = {
  readonly documents: readonly SatDocument[];
  readonly records: SatRecords;
};

/** The library from `docs/sat-md`'s files. */
export function buildSatLibrary(input: {
  readonly markdown: (file: string) => string | undefined;
  readonly sources: SatSourceManifest;
  readonly records: SatRecords;
}): SatLibrary {
  return {
    documents: SAT_DOCUMENTS.map(({ sourceId, file, ...metadata }) => {
      const markdown = input.markdown(file);
      if (!markdown) throw new Error(`SAT document ${file} is not available`);
      const source = input.sources[sourceId];
      return {
        ...metadata,
        markdown: compactSatMarkdown(markdown),
        source: source.url,
        publishedAt: source.publishedAt,
      };
    }),
    records: input.records,
  };
}

/**
 * A section of a document: from one heading to the next. The ingestion uploads each one as a
 * search passage (`corpus.ts`). Generated documents have Markdown headings; the guides, converted from PDF, start a node with `Nodo: Receptor` and an attribute
 * with its name at the line start (`RegimenFiscalReceptor Se debe registrar…`). A table stays
 * whole with its header, so a search never returns half a rule.
 */
export type SatSection = {
  readonly slug: string;
  /** Where the section sits, such as `Nodo: Receptor › UsoCFDI` or `c_RegimenFiscal`. */
  readonly label: string;
  readonly startLine: number;
  readonly endLine: number;
  readonly text: string;
};

/** Longer sections (appendices, worked examples) split at a blank line into parts this long. */
const SECTION_MAX_LINES = 40;

const HEADING = /^(#{1,6})\s+(.+)$/u;
const NODE = /^Nodo:\s*(\S.*)$/u;
const ATTRIBUTE =
  /^([A-Z][A-Za-z0-9]{2,})\s+(?:Se |Es |En |Atributo|Cuando|Para |Si |El |La |Este |Nodo|Expresa|Campo|Clave|Valor|Indica|Requerido|Opcional|Condicional)/u;

function splitSection(lines: readonly string[], start: number, end: number) {
  const parts: Array<[number, number]> = [];
  let from = start;
  while (end - from > SECTION_MAX_LINES) {
    let cut = from + SECTION_MAX_LINES;
    for (let line = cut; line > from + SECTION_MAX_LINES / 2; line -= 1) {
      if (!lines[line - 1]?.trim()) {
        cut = line;
        break;
      }
    }
    parts.push([from, cut]);
    from = cut;
  }
  parts.push([from, end]);
  return parts;
}

export function documentSections(document: SatDocument): SatSection[] {
  const lines = document.markdown.split("\n");
  const headings: Array<{ line: number; label: string }> = [];
  const path: string[] = [];
  let node = "";
  lines.forEach((line, index) => {
    const heading = HEADING.exec(line);
    if (heading) {
      const depth = heading[1]!.length;
      path.length = depth - 1;
      path[depth - 1] = heading[2]!.trim();
      // Below the document's own title, the title adds nothing to a section's place.
      const label = (depth > 1 ? path.slice(1) : path).filter(Boolean).join(" › ");
      headings.push({ line: index, label });
      return;
    }
    const nodeMatch = NODE.exec(line);
    if (nodeMatch) {
      // The PDF puts the node's description on its line: `Nodo: Receptor En este nodo…`.
      node = `Nodo: ${nodeMatch[1]!.split(/\s+/u)[0]}`;
      headings.push({ line: index, label: node });
      return;
    }
    const attribute = ATTRIBUTE.exec(line);
    if (attribute) {
      headings.push({ line: index, label: node ? `${node} › ${attribute[1]}` : attribute[1]! });
    }
  });
  if (headings[0]?.line !== 0) headings.unshift({ line: 0, label: document.title });
  const sections: SatSection[] = [];
  headings.forEach((heading, index) => {
    const end = headings[index + 1]?.line ?? lines.length;
    for (const [from, to] of splitSection(lines, heading.line, end)) {
      const text = lines.slice(from, to).join("\n");
      if (!text.trim()) continue;
      sections.push({
        slug: document.slug,
        label: heading.label,
        startLine: from + 1,
        endLine: to,
        text,
      });
    }
  });
  return sections;
}
